const lessons=[{"sentences":[{"speaker":"A","text":"Good morning I would like to book a walking tour for tomorrow morning.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.088875},{"speaker":"B","text":"Certainly we have a great historical tour available for visitors.","position":2,"audioStartSeconds":4.288875,"audioEndSeconds":8.776875},{"speaker":"A","text":"That sounds wonderful because I love learning about local history.","position":3,"audioStartSeconds":8.976875,"audioEndSeconds":12.922125},{"speaker":"B","text":"The start point is usually the museum but tomorrow we meet outside the central library.","position":4,"audioStartSeconds":13.122125,"audioEndSeconds":18.457958333333334},{"speaker":"A","text":"Oh thank goodness you told me because I would have gone to the wrong place.","position":5,"audioStartSeconds":18.657958333333333,"audioEndSeconds":22.768791666666665},{"speaker":"B","text":"Yes we changed the meeting location because of some road construction nearby.","position":6,"audioStartSeconds":22.968791666666668,"audioEndSeconds":27.775458333333333},{"speaker":"A","text":"How long does the entire walk usually last today.","position":7,"audioStartSeconds":27.975458333333332,"audioEndSeconds":31.416166666666665},{"speaker":"B","text":"It used to be three hours long although we reduced it to two hours.","position":8,"audioStartSeconds":31.61616666666667,"audioEndSeconds":36.11358333333333},{"speaker":"A","text":"Two hours is much better since I have another appointment later.","position":9,"audioStartSeconds":36.313583333333334,"audioEndSeconds":40.462291666666665},{"speaker":"B","text":"Wonderful and the cost is fifteen pounds per person.","position":10,"audioStartSeconds":40.66229166666667,"audioEndSeconds":44.57983333333333},{"speaker":"A","text":"Can I pay with cash when I arrive at the meeting point.","position":11,"audioStartSeconds":44.779833333333336,"audioEndSeconds":48.32366666666667},{"speaker":"B","text":"We cannot accept cash anymore so payment must be made online beforehand.","position":12,"audioStartSeconds":48.523666666666664,"audioEndSeconds":53.70408333333334},{"speaker":"A","text":"Alright I will pay by card right now on your website.","position":13,"audioStartSeconds":53.90408333333333,"audioEndSeconds":57.59079166666667},{"speaker":"B","text":"Perfect your booking is confirmed.","position":14,"audioStartSeconds":57.790791666666664,"audioEndSeconds":60.693583333333336}],"questions":[{"prompt":"Meeting location: ______","answer":"central library","evidenceSentence":4,"evidence":"outside the central library","explanation":"Người nghe ban đầu định đến viện bảo tàng nhưng điểm bắt đầu đã đổi ra bên ngoài thư viện trung tâm."},{"prompt":"Reason for change: ______","answer":"road construction","evidenceSentence":6,"evidence":"road construction","explanation":"Lý do thay đổi địa điểm là do có công trình làm đường ở gần đó."},{"prompt":"Original duration: ______ hours","answer":"three","evidenceSentence":8,"evidence":"three hours","explanation":"Thời lượng ban đầu của chuyến đi là ba giờ trước khi được rút ngắn."},{"prompt":"New duration: ______ hours","answer":"two","evidenceSentence":8,"evidence":"two hours","explanation":"Thời lượng mới của chuyến đi bộ là hai giờ."},{"prompt":"Price per person: ______ pounds","answer":"fifteen","evidenceSentence":10,"evidence":"fifteen pounds","explanation":"Chi phí cho mỗi người tham gia là mười lăm bảng."},{"prompt":"Accepted payment method: ______","answer":"online","evidenceSentence":12,"evidence":"online","explanation":"Thanh toán phải được thực hiện trực tuyến trước vì họ không nhận tiền mặt nữa."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
